 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    sep = 5 if any(5 in row for row in grid) else 8
    row_bands = []
    start = 0
    for r in range(h):
        if all(v == sep for v in grid[r]):
            if start < r:
                row_bands.append((start, r))
            start = r + 1
    if start < h:
        row_bands.append((start, h))
    col_bands = []
    start = 0
    for c in range(w):
        if all(grid[r][c] == sep for r in range(h)):
            if start < c:
                col_bands.append((start, c))
            start = c + 1
    if start < w:
        col_bands.append((start, w))

    # The marker in the first compartment of each row band gives that band's color.
    row_colors = []
    for r0, r1 in row_bands:
        counts = {}
        for r in range(r0, r1):
            for c in range(*col_bands[0]):
                v = grid[r][c]
                if v != 0 and v != sep:
                    counts[v] = counts.get(v, 0) + 1
        row_colors.append(max(counts, key=counts.get))

    # Find the one non-marker compartment containing the pattern, and retain its shape.
    pattern = None
    for ri, (r0, r1) in enumerate(row_bands):
        for ci, (c0, c1) in enumerate(col_bands):
            if ci == 0:
                continue
            cells = [(r-r0, c-c0) for r in range(r0, r1) for c in range(c0, c1)
                     if grid[r][c] not in (0, sep)]
            if cells:
                pattern = cells
                break
        if pattern:
            break
    if pattern is None:
        raise ValueError('No pattern found')

    out = [[0] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == sep:
                out[r][c] = sep
    for ri, (r0, r1) in enumerate(row_bands):
        for c0, c1 in col_bands:
            for dr, dc in pattern:
                if r0 + dr < r1 and c0 + dc < c1:
                    out[r0 + dr][c0 + dc] = row_colors[ri]
    return out

if __name__ == '__main__':
